"""Normalize free-form VAD job options into concrete ASR kwargs."""

from __future__ import annotations

from typing import Any


# Free defaults: medium sensitivity
DEFAULT_THRESHOLD = 0.5
DEFAULT_MIN_SPEECH_MS = 300
DEFAULT_MIN_SILENCE_MS = 100
DEFAULT_SPEECH_PAD_MS = 200

# Aggressive free preset: prefer clean cuts over catching whispers
AGGRESSIVE_THRESHOLD = 0.6
AGGRESSIVE_MIN_SPEECH_MS = 350
AGGRESSIVE_MIN_SILENCE_MS = 150
AGGRESSIVE_SPEECH_PAD_MS = 180

# Sensitive free preset: catch soft dialogue / low-energy vocalization
SENSITIVE_THRESHOLD = 0.18
SENSITIVE_MIN_SPEECH_MS = 60
SENSITIVE_MIN_SILENCE_MS = 140
SENSITIVE_SPEECH_PAD_MS = 350

# Film / Advanced preset after vocal separation.
# Slightly stricter than soft-AV: cut BGM micro-islands and merge dialogue pauses.
FILM_THRESHOLD = 0.55
FILM_MIN_SPEECH_MS = 350
FILM_MIN_SILENCE_MS = 280
FILM_SPEECH_PAD_MS = 200


def _as_float(value: Any, default: float) -> float:
    try:
        n = float(value)
    except (TypeError, ValueError):
        return default
    if not (n == n):  # NaN
        return default
    return n


def _as_int(value: Any, default: int) -> int:
    try:
        return int(float(value))
    except (TypeError, ValueError):
        return default


def _resolve_hallucination_silence_threshold(src: dict[str, Any]) -> float | None:
    """Optional Whisper skip of long silences (seconds). None / <=0 = off."""
    raw = src.get(
        "hallucinationSilenceThreshold",
        src.get("hallucination_silence_threshold"),
    )
    if raw is None:
        return None
    if isinstance(raw, str) and not raw.strip():
        return None
    n = _as_float(raw, float("nan"))
    if not (n == n) or n <= 0:
        return None
    return max(0.1, min(30.0, n))


def normalize_vad_options(
    raw: dict[str, Any] | None,
    *,
    film_preset: bool = False,
) -> dict[str, Any]:
    """
    Build a normalized VAD options dict.

    Precedence for numeric defaults:
    1. Explicit numeric fields from the client (always win)
    2. filmPreset / film mode (Advanced) — defaults only, no hard floor
    3. sensitive free toggle (preferred over aggressive when both set)
    4. aggressive free toggle
    5. medium defaults
    """
    src = raw if isinstance(raw, dict) else {}
    enabled = src.get("enabled", True) is not False
    sensitive = bool(src.get("sensitive"))
    aggressive = bool(src.get("aggressive")) and not sensitive
    film = film_preset or bool(src.get("filmPreset"))

    if film:
        threshold = FILM_THRESHOLD
        min_speech = FILM_MIN_SPEECH_MS
        min_silence = FILM_MIN_SILENCE_MS
        speech_pad = FILM_SPEECH_PAD_MS
        default_max_seg = 15000
    elif sensitive:
        threshold = SENSITIVE_THRESHOLD
        min_speech = SENSITIVE_MIN_SPEECH_MS
        min_silence = SENSITIVE_MIN_SILENCE_MS
        speech_pad = SENSITIVE_SPEECH_PAD_MS
        default_max_seg = 30000
    elif aggressive:
        threshold = AGGRESSIVE_THRESHOLD
        min_speech = AGGRESSIVE_MIN_SPEECH_MS
        min_silence = AGGRESSIVE_MIN_SILENCE_MS
        speech_pad = AGGRESSIVE_SPEECH_PAD_MS
        default_max_seg = 20000
    else:
        threshold = DEFAULT_THRESHOLD
        min_speech = DEFAULT_MIN_SPEECH_MS
        min_silence = DEFAULT_MIN_SILENCE_MS
        speech_pad = DEFAULT_SPEECH_PAD_MS
        default_max_seg = 30000

    if "threshold" in src and src.get("threshold") is not None:
        threshold = _as_float(src.get("threshold"), threshold)
    if "minSpeechMs" in src or "min_speech_duration_ms" in src:
        speech_key = src.get("minSpeechMs", src.get("min_speech_duration_ms"))
        if speech_key is not None:
            min_speech = _as_int(speech_key, min_speech)
    if "minSilenceMs" in src or "min_silence_duration_ms" in src:
        silence_key = src.get("minSilenceMs", src.get("min_silence_duration_ms"))
        if silence_key is not None:
            min_silence = _as_int(silence_key, min_silence)
    if "speechPadMs" in src or "speech_pad_ms" in src:
        pad_key = src.get("speechPadMs", src.get("speech_pad_ms"))
        if pad_key is not None:
            speech_pad = _as_int(pad_key, speech_pad)

    # Clamp only — do not hard-floor film values over explicit client knobs.
    threshold = max(0.1, min(0.95, threshold))
    min_speech = max(0, min(10000, min_speech))
    min_silence = max(0, min(10000, min_silence))
    speech_pad = max(0, min(5000, speech_pad))

    has_explicit_max = (
        "maxSingleSegmentMs" in src or "max_single_segment_time" in src
    ) and (
        src.get("maxSingleSegmentMs", src.get("max_single_segment_time")) is not None
    )
    max_single_segment_ms = _as_int(
        src.get("maxSingleSegmentMs", src.get("max_single_segment_time")),
        default_max_seg,
    )
    if not has_explicit_max:
        max_single_segment_ms = default_max_seg
    max_single_segment_ms = max(5000, min(60000, max_single_segment_ms))

    hallu = _resolve_hallucination_silence_threshold(src)
    if hallu is None and film:
        # Music beds invent punctuation / filler cues across long gaps.
        hallu = 2.0

    return {
        "enabled": enabled,
        "sensitive": sensitive,
        "aggressive": aggressive and not film,
        "filmPreset": film,
        "threshold": threshold,
        "minSpeechMs": min_speech,
        "minSilenceMs": min_silence,
        "speechPadMs": speech_pad,
        "maxSingleSegmentMs": max_single_segment_ms,
        "hallucinationSilenceThreshold": hallu,
        "model": str(src.get("model") or "").strip(),
    }


def whisper_vad_kwargs(opts: dict[str, Any]) -> dict[str, Any]:
    """Kwargs for faster-whisper VadOptions / transcribe(vad_parameters=...).

    Sensitive mode disables Silero VAD entirely: soft dialogue during intimate /
    low-energy scenes is routinely classified as non-speech by the VAD and never
    reaches ASR when the filter stays on.
    """
    if not opts.get("enabled", True) or opts.get("sensitive"):
        return {"vad_filter": False}
    return {
        "vad_filter": True,
        "vad_parameters": {
            "threshold": float(opts["threshold"]),
            "min_speech_duration_ms": int(opts["minSpeechMs"]),
            "min_silence_duration_ms": int(opts["minSilenceMs"]),
            "speech_pad_ms": int(opts["speechPadMs"]),
        },
    }


def sensevoice_vad_kwargs(opts: dict[str, Any]) -> dict[str, Any]:
    """
    FunASR fsmn-vad kwargs.

    Only pass keys that FunASR AutoModel reliably accepts. Extra model_conf
    overrides (speech_noise_thres, silence thresholds, …) have been observed to
    yield zero speech segments / empty transcripts on some FunASR builds.
    UI threshold/pad knobs still affect Whisper via whisper_vad_kwargs, and
    SenseVoice merge/segment length via maxSingleSegmentMs + merge_length_s.
    """
    if not opts.get("enabled", True):
        return {}
    max_seg = int(opts.get("maxSingleSegmentMs") or 30000)
    return {
        "max_single_segment_time": max(5000, min(60000, max_seg)),
    }


def sensevoice_merge_length_s(opts: dict[str, Any] | None) -> float:
    """Shorter VAD merges when user asked for aggressive / film slicing."""
    src = opts if isinstance(opts, dict) else {}
    if src.get("filmPreset"):
        return 5.0
    if src.get("aggressive"):
        return 6.0
    if src.get("sensitive"):
        return 8.0
    return 8.0
